<script setup lang="ts">
import{onMounted,ref}from'vue';import DefaultLayout from'@/layouts/DefaultLayout.vue';import BaseInput from'@/components/ui/BaseInput.vue';import BaseButton from'@/components/ui/BaseButton.vue';import{useApi}from'@/composables/useApi';import{useAuthStore}from'@/stores/auth';import type{ApiResponse,User}from'@/types';
const auth=useAuthStore(),api=useApi(),fullName=ref(''),avatarUrl=ref(''),message=ref(''),error=ref('');
onMounted(async()=>{try{const user=await auth.fetchCurrentUser();if(user){fullName.value=user.fullName;avatarUrl.value=user.avatarUrl||''}}catch(e){error.value=e instanceof Error?e.message:'Không thể tải hồ sơ'}});
async function save(){try{const r=await api.patch<ApiResponse<User>>('/users/me',{fullName:fullName.value.trim(),avatarUrl:avatarUrl.value.trim()||null});if(r.data)auth.updateUser(r.data);message.value='Đã cập nhật hồ sơ';error.value=''}catch(e){error.value=e instanceof Error?e.message:'Không thể cập nhật'}}
</script>
<template><DefaultLayout><main class="mx-auto max-w-2xl px-4 py-12"><h1 class="text-3xl font-black dark:text-white">Hồ sơ của tôi</h1><p class="mt-2 mb-7 text-slate-500">Cập nhật tên và ảnh đại diện</p><form class="space-y-5 rounded-2xl border bg-white p-6 dark:border-slate-800 dark:bg-slate-900" @submit.prevent="save"><div v-if="avatarUrl" class="flex justify-center"><img :src="avatarUrl" class="h-24 w-24 rounded-full object-cover"></div><BaseInput id="profile-name" v-model="fullName" label="Họ và tên" required/><BaseInput id="profile-email" :model-value="auth.user?.email||''" label="Email" disabled/><BaseInput id="profile-avatar" v-model="avatarUrl" label="URL ảnh đại diện"/><p v-if="message" class="text-emerald-600">{{message}}</p><p v-if="error" class="text-red-600">{{error}}</p><BaseButton type="submit" :loading="api.loading.value">Lưu thay đổi</BaseButton></form></main></DefaultLayout></template>
